#!/usr/bin/env python3
"""Read-only report tests using artifact layouts generated by the mocked driver."""

from contextlib import redirect_stderr, redirect_stdout
import io
import json
from pathlib import Path
import unittest

import run_width_depth_search_test as driver_tests
from summarize_width_depth import (
    SCHEDULE_FIELDS, frontier, load_runs, main, protocol_groups, render_markdown,
)


class SummarizeWidthDepthTest(unittest.TestCase):
    def make_run(self, *, depths=None, widths=None, failures=None, steps=5000, seed=1337,
                 attention_heads=None, **controls):
        # Reuse the driver's no-GPU fake to keep these fixtures synchronized with
        # real command/result/audit schemas. It launches no subprocess or GPU work.
        fixture = driver_tests.WidthDepthSearchTest()
        fixture.setUp()
        self.addCleanup(fixture.doCleanups)
        if depths is not None:
            fixture.args.depths = depths
        if widths is not None:
            fixture.args.widths = widths
        if failures is not None:
            fixture.failures = failures
        fixture.args.steps = steps
        fixture.args.seed = seed
        if attention_heads is not None:
            fixture.args.attention_heads = attention_heads
        for field, value in controls.items():
            self.assertIn(field, SCHEDULE_FIELDS)
            setattr(fixture.args, field, value)
        self.assertEqual(fixture.run_driver(), 0)
        path = fixture.args.output_dir / "width_depth_search_summary.json"
        return path

    def mutate_manifest(self, path, mutate):
        manifest = json.loads(path.read_text())
        mutate(manifest)
        path.write_text(json.dumps(manifest))

    def test_report_reads_verified_successes_and_failures_from_saved_evidence(self):
        path = self.make_run()
        runs = load_runs([path], ["coarse"])
        self.assertEqual(len(runs[0]["trials"]), 5)
        report = render_markdown(runs)
        self.assertIn("budget exhausted", report)
        self.assertIn("memorized", report)
        self.assertIn("untested: search moved on", report)
        self.assertIn("pooled", report.lower())
        self.assertIn("no GPU inference was rerun", report)
        self.assertEqual([(trial["layers"], trial["width"]) for trial in frontier(runs[0]["trials"])],
                         [(1, 128), (2, 64), (3, 32)])

    def test_minimum_and_frontier_are_recomputed_not_trusted_from_manifest(self):
        path = self.make_run(failures=set())
        def corrupt_cached_claims(manifest):
            manifest["minimum_parameter_success"] = {"parameters": 1}
            manifest["verified_success_frontier"] = [{"layers": 0, "width": 1}]
        self.mutate_manifest(path, corrupt_cached_claims)
        runs = load_runs([path])
        points = frontier(runs[0]["trials"])
        self.assertEqual(len(points), 1)
        self.assertEqual((points[0]["layers"], points[0]["width"]), (1, 32))
        self.assertIn("1,654,240", render_markdown(runs))

    def test_same_architecture_different_budgets_preserves_failure_and_success(self):
        short = self.make_run(depths=[1], widths=[64], failures={(1, 64)})
        long = self.make_run(depths=[1], widths=[64], failures=set(), steps=20000)
        runs = load_runs([short, long], ["5k", "20k"])
        trials = [trial for run in runs for trial in run["trials"]]
        self.assertEqual(len(trials), 2)
        self.assertEqual([trial["status"] for trial in trials],
                         ["verified_budget_failure", "verified_success"])
        self.assertEqual([trial["run"] for trial in frontier(trials)], ["20k"])
        report = render_markdown(runs)
        self.assertIn("| 5k | 5000 |", report)
        self.assertIn("| 20k | 20000 |", report)
        self.assertIn("| 5k | 1 | 64 |", report)
        self.assertIn("| 20k | 1 | 64 |", report)

    def test_different_seeds_remain_distinct_success_observations(self):
        first = self.make_run(depths=[1], widths=[64], failures=set(), seed=1337)
        second = self.make_run(depths=[1], widths=[64], failures=set(), seed=42)
        runs = load_runs([first, second], ["seed1337", "seed42"])
        points = frontier([trial for run in runs for trial in run["trials"]])
        self.assertEqual(len(points), 2)
        self.assertEqual({trial["seed"] for trial in points}, {1337, 42})
        report = render_markdown(runs)
        self.assertIn("| seed42 | 5000 | 10800 | 16 | 42 |", report)

    def test_matching_controls_merge_across_architectures_and_head_policies(self):
        legacy = self.make_run(depths=[1], widths=[64], failures=set())
        self.mutate_manifest(legacy, lambda manifest:
                             manifest["configuration"].pop("attention_heads"))
        default = self.make_run(depths=[2], widths=[24], failures=set(), attention_heads=0)
        explicit = self.make_run(depths=[1], widths=[16], failures=set(), attention_heads=1)
        runs = load_runs([legacy, default, explicit], ["legacy", "default", "explicit"])
        groups = protocol_groups(runs)
        self.assertEqual(len(groups), 1)
        self.assertEqual(groups[0]["labels"], ["legacy", "default", "explicit"])
        self.assertEqual(groups[0]["binary_sha256"], runs[0]["binary_sha256"])
        self.assertEqual(groups[0]["configuration"],
                         {field: runs[0]["configuration"][field] for field in SCHEDULE_FIELDS})
        self.assertEqual([(trial["run"], trial["layers"], trial["width"], trial["heads"])
                          for trial in groups[0]["trials"]],
                         [("legacy", 1, 64, 1), ("default", 2, 24, 3), ("explicit", 1, 16, 1)])
        report = render_markdown(runs)
        self.assertIn("## Matched-protocol measured depth/width frontiers", report)
        self.assertIn("### Protocol 1: legacy, default, explicit", report)

    def test_every_training_control_separates_protocol_groups(self):
        alternatives = {
            "steps": 20000, "training_seconds": 0, "batch_size": 8, "seed": 42,
            "learning_rate": 0.001, "warmup_steps": 200, "eval_every": 64,
            "checkpoint_every": 256,
        }
        self.assertEqual(set(alternatives), set(SCHEDULE_FIELDS))
        for field, value in alternatives.items():
            with self.subTest(field=field):
                baseline = self.make_run(depths=[1], widths=[64], failures=set())
                changed = self.make_run(depths=[1], widths=[64], failures=set(), **{field: value})
                groups = protocol_groups(load_runs([baseline, changed], ["baseline", "changed"]))
                self.assertEqual([group["labels"] for group in groups], [["baseline"], ["changed"]])
                self.assertEqual(groups[1]["configuration"][field], value)

    def test_full_binary_identity_separates_otherwise_matching_protocols(self):
        first = self.make_run(depths=[1], widths=[64], failures=set())
        second = self.make_run(depths=[1], widths=[64], failures=set())
        first_hash, second_hash = "a" * 12 + "0" * 52, "a" * 12 + "1" * 52
        self.mutate_manifest(first, lambda manifest: manifest.update(binary_sha256=first_hash))
        self.mutate_manifest(second, lambda manifest: manifest.update(binary_sha256=second_hash))
        groups = protocol_groups(load_runs([first, second], ["first", "second"]))
        self.assertEqual([group["labels"] for group in groups], [["first"], ["second"]])
        self.assertEqual([group["binary_sha256"] for group in groups], [first_hash, second_hash])

    def test_protocol_groups_preserve_first_seen_group_and_run_order(self):
        first = self.make_run(depths=[1], widths=[64], failures=set())
        other = self.make_run(depths=[1], widths=[64], failures=set(), steps=20000)
        matching = self.make_run(depths=[2], widths=[32], failures=set())
        groups = protocol_groups(load_runs([first, other, matching], ["first", "other", "matching"]))
        self.assertEqual([group["labels"] for group in groups], [["first", "matching"], ["other"]])
        self.assertEqual([[trial["run"] for trial in group["trials"]] for group in groups],
                         [["first", "matching"], ["other"]])

    def protocol_section(self, report, number, labels):
        heading = f"### Protocol {number}: {', '.join(labels)}\n"
        self.assertIn(heading, report)
        body = report.split(heading, 1)[1]
        return body.split("\n### Protocol ", 1)[0].split("\n## ", 1)[0]

    def test_matched_frontier_and_minimum_exclude_lower_parameter_failure(self):
        success = self.make_run(depths=[1], widths=[64], failures=set())
        failure = self.make_run(depths=[1], widths=[32], failures={(1, 32)})
        runs = load_runs([success, failure], ["success", "failure"])
        group = protocol_groups(runs)[0]
        self.assertEqual(len(group["trials"]), 2)
        self.assertEqual([trial["run"] for trial in frontier(group["trials"])], ["success"])
        section = self.protocol_section(render_markdown(runs), 1, ["success", "failure"])
        self.assertEqual(section.count("| success | 1 | 64 |"), 2)
        self.assertNotIn("| failure |", section)
        self.assertNotIn("1,654,240", section)
        self.assertNotIn("budget exhausted", section)

    def test_matched_frontier_retains_success_dominated_only_under_other_protocol(self):
        coarse = self.make_run(depths=[1], widths=[128], failures=set())
        long = self.make_run(depths=[1], widths=[32], failures=set(), steps=20000)
        runs = load_runs([coarse, long], ["coarse", "long"])
        report = render_markdown(runs)
        coarse_section = self.protocol_section(report, 1, ["coarse"])
        long_section = self.protocol_section(report, 2, ["long"])
        self.assertEqual(coarse_section.count("| coarse | 1 | 128 |"), 2)
        self.assertNotIn("| long |", coarse_section)
        self.assertEqual(long_section.count("| long | 1 | 32 |"), 2)
        self.assertNotIn("| coarse |", long_section)
        pooled = report.split("## Pooled measured depth/width frontier\n", 1)[1].split("\n## ", 1)[0]
        self.assertIn("| long | 1 | 32 |", pooled)
        self.assertNotIn("| coarse |", pooled)
        self.assertIn("## Minimum-parameter verified success", report)

    def test_protocol_without_completed_trials_remains_explicit(self):
        path = self.make_run(depths=[1], widths=[64], failures=set())
        def make_pending(manifest):
            manifest["status"] = "running"
            manifest["trials"] = [{"layers": 1, "width": 64,
                                   "status": "running", "phase": "training"}]
        self.mutate_manifest(path, make_pending)
        runs = load_runs([path], ["pending"])
        groups = protocol_groups(runs)
        self.assertEqual(len(groups), 1)
        self.assertEqual(groups[0]["labels"], ["pending"])
        self.assertEqual(groups[0]["trials"], [])
        section = self.protocol_section(render_markdown(runs), 1, ["pending"])
        self.assertRegex(section.lower(), "no verified success")
        self.assertNotIn("| pending |", section)

    def test_protocol_with_only_failures_does_not_invent_success_or_minimum(self):
        path = self.make_run(depths=[1], widths=[32], failures={(1, 32)})
        runs = load_runs([path], ["failed"])
        group = protocol_groups(runs)[0]
        self.assertEqual(len(group["trials"]), 1)
        self.assertEqual(frontier(group["trials"]), [])
        section = self.protocol_section(render_markdown(runs), 1, ["failed"])
        self.assertRegex(section.lower(), "no verified success")
        self.assertNotIn("| failed |", section)
        self.assertNotIn("1,654,240", section)

    def test_alternate_valid_heads_are_not_conflated_with_default_heads(self):
        first = self.make_run(depths=[1], widths=[64], failures=set())
        second = self.make_run(depths=[1], widths=[64], failures=set(), attention_heads=2)
        runs = load_runs([first, second], ["onehead", "twoheads"])
        points = frontier([trial for run in runs for trial in run["trials"]])
        self.assertEqual(len(points), 2)
        self.assertEqual({trial["heads"] for trial in points}, {1, 2})
        self.assertIn("2 × 32", render_markdown(runs))

    def test_legacy_manifest_without_head_override_uses_gcd_policy(self):
        path = self.make_run(depths=[1], widths=[24], failures=set())
        self.mutate_manifest(path, lambda manifest:
                             manifest["configuration"].pop("attention_heads", None))
        trial = load_runs([path])[0]["trials"][0]
        self.assertEqual((trial["heads"], trial["head_dim"]), (3, 8))

    def test_explicit_zero_head_override_uses_gcd_policy(self):
        path = self.make_run(depths=[1], widths=[24], failures=set(), attention_heads=0)
        trial = load_runs([path])[0]["trials"][0]
        self.assertEqual((trial["heads"], trial["head_dim"]), (3, 8))

    def test_positive_head_override_accepts_compact_one_head_trials(self):
        path = self.make_run(depths=[1], widths=[24, 8], failures=set(), attention_heads=1)
        runs = load_runs([path], ["onehead"])
        self.assertEqual([(trial["width"], trial["heads"], trial["head_dim"])
                          for trial in runs[0]["trials"]], [(24, 1, 24), (8, 1, 8)])
        self.assertIn("| onehead | 1 | 24 | 1 × 24 |", render_markdown(runs))

    def test_head_override_must_match_resolved_trial_heads(self):
        path = self.make_run(depths=[1], widths=[64], failures=set())
        self.mutate_manifest(path, lambda manifest:
                             manifest["configuration"].update(attention_heads=2))
        with self.assertRaisesRegex(ValueError, "attention heads disagree"):
            load_runs([path])

    def test_missing_or_zero_head_override_rejects_non_gcd_trial_heads(self):
        for legacy in (True, False):
            with self.subTest(legacy=legacy):
                path = self.make_run(depths=[1], widths=[24], failures=set(), attention_heads=1)
                def clear_override(manifest):
                    if legacy:
                        manifest["configuration"].pop("attention_heads")
                    else:
                        manifest["configuration"]["attention_heads"] = 0
                self.mutate_manifest(path, clear_override)
                with self.assertRaisesRegex(ValueError, "attention heads disagree"):
                    load_runs([path])

    def test_positive_head_override_still_requires_matching_head_dimension(self):
        path = self.make_run(depths=[1], widths=[24], failures=set(), attention_heads=1)
        self.mutate_manifest(path, lambda manifest:
                             manifest["trials"][0].update(head_dim=8))
        with self.assertRaisesRegex(ValueError, "head dimension is inconsistent"):
            load_runs([path])

    def test_invalid_head_override_configuration_is_rejected(self):
        for invalid in (-1, True, 1.5, "1", None):
            with self.subTest(invalid=invalid):
                path = self.make_run(depths=[1], widths=[64], failures=set())
                self.mutate_manifest(path, lambda manifest:
                                     manifest["configuration"].update(attention_heads=invalid))
                with self.assertRaisesRegex(ValueError, "attention_heads must be an integer"):
                    load_runs([path])

    def test_head_override_must_divide_even_untested_configured_widths(self):
        path = self.make_run(depths=[1], widths=[24, 8], failures={(1, 24)})
        self.mutate_manifest(path, lambda manifest:
                             manifest["configuration"].update(attention_heads=3))
        with self.assertRaisesRegex(ValueError, "divide every configured width"):
            load_runs([path])

    def test_running_trial_with_no_artifacts_is_explicitly_ignored(self):
        path = self.make_run()
        def append_running(manifest):
            manifest["status"] = "running"
            manifest["trials"].append({"layers": 4, "width": 16,
                                       "phase": "training", "status": "running"})
        self.mutate_manifest(path, append_running)
        runs = load_runs([path])
        self.assertEqual(len(runs[0]["trials"]), 5)
        self.assertEqual(len(runs[0]["ignored"]), 1)
        self.assertIn("unverified: running (training); not counted as a budget failure", render_markdown(runs))

    def test_execution_error_is_not_reported_as_budget_failure(self):
        path = self.make_run()
        def append_error(manifest):
            manifest["status"] = "error"
            manifest["trials"].append({"layers": 4, "width": 16,
                                       "phase": "checkpoint_verification", "status": "error"})
        self.mutate_manifest(path, append_error)
        report = render_markdown(load_runs([path]))
        self.assertIn("unverified: error (checkpoint_verification)", report)
        self.assertIn("search status: error", report)

    def test_only_budget_failures_do_not_invent_a_minimum(self):
        path = self.make_run(depths=[1], widths=[64], failures={(1, 64)})
        report = render_markdown(load_runs([path]))
        self.assertIn("No verified success yet.", report)
        self.assertIn("Not yet established by the supplied runs.", report)

    def test_compact_widths_keep_unpadded_parameters_and_head_partitions(self):
        path = self.make_run(depths=[1, 2, 3], widths=[24, 8, 3],
                             failures={(1, 8), (2, 3)})
        runs = load_runs([path], ["compact"])
        points = frontier(runs[0]["trials"])
        self.assertEqual([(trial["layers"], trial["width"]) for trial in points],
                         [(1, 24), (2, 8), (3, 3)])
        report = render_markdown(runs)
        self.assertIn("| compact | 1 | 24 | 3 × 8 | 96 | 1,238,376 |", report)
        self.assertIn("| compact | 3 | 3 | 3 × 1 | 12 | 154,335 |", report)

    def test_compact_head_dimension_still_requires_positive_matching_integer(self):
        for invalid in (0, -1, True, 7, 8.0):
            with self.subTest(invalid=invalid):
                path = self.make_run(depths=[1], widths=[8], failures=set())
                self.mutate_manifest(path, lambda manifest:
                                     manifest["trials"][0].update(head_dim=invalid))
                with self.assertRaises(ValueError):
                    load_runs([path])

    def test_missing_training_result_fails_closed(self):
        path = self.make_run()
        trial = json.loads(path.read_text())["trials"][0]
        (Path(trial["output_dir"]) / "result.txt").unlink()
        with self.assertRaises(OSError):
            load_runs([path])

    def test_missing_independent_audit_fails_closed(self):
        path = self.make_run()
        trial = json.loads(path.read_text())["trials"][0]
        Path(trial["prediction_artifact_verification"]).unlink()
        with self.assertRaises(OSError):
            load_runs([path])

    def test_missing_tokenizer_snapshot_fails_closed(self):
        path = self.make_run()
        trial = json.loads(path.read_text())["trials"][0]
        (Path(trial["output_dir"]) / "tokenizer.json").unlink()
        with self.assertRaises(OSError):
            load_runs([path])

    def test_native_result_corruption_is_detected(self):
        path = self.make_run()
        trial = json.loads(path.read_text())["trials"][0]
        native = Path(trial["output_dir"]) / "independent_verification/result.txt"
        native.write_text(native.read_text().replace("errors=0", "errors=1"))
        with self.assertRaisesRegex(ValueError, "Saved native results disagree"):
            load_runs([path])

    def test_mutated_prediction_even_in_both_copies_fails_its_audit_hash(self):
        path = self.make_run()
        trial = json.loads(path.read_text())["trials"][0]
        for relative in ("final_predictions.tsv", "independent_verification/final_predictions.tsv"):
            (Path(trial["output_dir"]) / relative).write_text("corrupt predictions\n")
        with self.assertRaisesRegex(ValueError, "predictions_sha256"):
            load_runs([path])

    def test_input_snapshot_corruption_is_detected(self):
        path = self.make_run()
        trial = json.loads(path.read_text())["trials"][0]
        (Path(trial["output_dir"]) / "corpus.txt").write_text("corrupt corpus\n")
        with self.assertRaisesRegex(ValueError, "Changed corpus"):
            load_runs([path])

    def test_audit_count_and_loss_corruption_are_detected(self):
        for field, value in (("errors", 1), ("success", 1), ("mean_loss_nats", "nan"),
                             ("mean_loss_nats", 3.0)):
            with self.subTest(field=field, value=value):
                path = self.make_run()
                trial = json.loads(path.read_text())["trials"][0]
                audit_path = Path(trial["prediction_artifact_verification"])
                audit = json.loads(audit_path.read_text())
                audit[field] = value
                audit_path.write_text(json.dumps(audit))
                with self.assertRaises(ValueError):
                    load_runs([path])

    def test_changed_named_budget_disagrees_with_recorded_training_command(self):
        path = self.make_run(depths=[1], widths=[128], failures=set())
        self.mutate_manifest(path, lambda manifest: manifest["configuration"].update(steps=20000))
        with self.assertRaisesRegex(ValueError, "training command: expected steps="):
            load_runs([path])

    def test_wrong_parameter_count_is_rejected(self):
        path = self.make_run()
        self.mutate_manifest(path, lambda manifest: manifest["trials"][0].update(parameters=1))
        with self.assertRaisesRegex(ValueError, "parameter count"):
            load_runs([path])

    def test_unknown_status_or_unverified_phase_is_rejected(self):
        for mutation in ({"status": "probably_success"}, {"phase": "training"}):
            with self.subTest(mutation=mutation):
                path = self.make_run()
                self.mutate_manifest(path, lambda manifest: manifest["trials"][0].update(mutation))
                with self.assertRaises(ValueError):
                    load_runs([path])

    def test_duplicate_or_tested_and_skipped_configuration_is_rejected(self):
        for duplicate_trial in (True, False):
            with self.subTest(duplicate_trial=duplicate_trial):
                path = self.make_run()
                def duplicate(manifest):
                    if duplicate_trial:
                        manifest["trials"].append(manifest["trials"][0])
                    else:
                        manifest["skipped_configurations"].append({"layers": 1, "width": 128,
                                                                   "reason": "dominated_by_verified_success"})
                self.mutate_manifest(path, duplicate)
                with self.assertRaises(ValueError):
                    load_runs([path])

    def test_different_corpus_identity_cannot_be_pooled(self):
        first = self.make_run()
        second = self.make_run()
        self.mutate_manifest(second, lambda manifest: manifest.update(corpus_sha256="a" * 64))
        with self.assertRaisesRegex(ValueError, "different corpus/tokenizer"):
            load_runs([first, second], ["first", "second"])

    def test_labels_and_summary_paths_must_be_unique(self):
        first, second = self.make_run(), self.make_run()
        for paths, labels in (([first, first], ["a", "b"]),
                              ([first, second], ["a", "a"]),
                              ([first, second], ["a"]), ([first], [""])):
            with self.subTest(paths=paths, labels=labels), self.assertRaises(ValueError):
                load_runs(paths, labels)

    def test_cli_prints_nothing_if_any_completed_evidence_is_invalid(self):
        first = self.make_run()
        second = self.make_run()
        trial = json.loads(second.read_text())["trials"][0]
        Path(trial["prediction_artifact_verification"]).unlink()
        output, errors = io.StringIO(), io.StringIO()
        with redirect_stdout(output), redirect_stderr(errors):
            status = main([str(first), str(second), "--labels=valid,invalid"])
        self.assertEqual(status, 1)
        self.assertEqual(output.getvalue(), "")
        self.assertIn("Cannot validate", errors.getvalue())

    def test_cli_is_read_only_and_escapes_markdown_labels(self):
        path = self.make_run()
        original = {file: file.read_bytes() for file in path.parent.rglob("*") if file.is_file()}
        output = io.StringIO()
        with redirect_stdout(output):
            status = main([str(path), "--labels=coarse|run"])
        self.assertEqual(status, 0)
        self.assertIn("coarse\\|run", output.getvalue())
        self.assertEqual(original, {file: file.read_bytes() for file in path.parent.rglob("*") if file.is_file()})


if __name__ == "__main__":
    unittest.main()
